import React, { useEffect, useRef, useState } from 'react';
import './Product.css';
import Img1 from "../assets/images/img1.jpeg";
import Img2 from "../assets/images/img2.jpeg";
import Img3 from "../assets/images/img3.jpeg";
import Img4 from "../assets/images/img4.jpeg";
import Img5 from "../assets/images/img5.jpeg";
import Img6 from "../assets/images/img6.jpeg";

const Products = () => {
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const products = [
    {
      id: 1,
      name: "Smart Thermostat",
      image: Img1,
      description: "Control your home's temperature remotely with smart sensors and schedules."
    },
    {
      id: 2,
      name: "Smart Lighting",
      image: Img2,
      description: "Energy-efficient, mood-adaptive lighting for smarter living."
    },
    {
      id: 3,
      name: "Smart Switch",
      image: Img3,
      description: "Control your appliances remotely and automate routines."
    },
    {
      id: 4,
      name: "Automated Curtains",
      image: Img4,
      description: "Automate your blinds and curtains with ease."
    },
    {
      id: 5,
      name: "Automated Curtains",
      image: Img5,
      description: "Automate your blinds and curtains with ease."
    },
    {
      id: 6,
      name: "Automated Curtains",
      image: Img6,
      description: "Automate your blinds and curtains with ease."
    }
    // Add more products if needed
  ];

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.3 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <>
      <section
        ref={sectionRef}
        className={`products-section fade-in-section ${isVisible ? 'visible' : ''}`}
      >
        <div className="container">
          <h2 className="products-title">Our Products</h2>

          <div className="products-grid">
            {products.map((product, index) => (
              <div
                key={product.id}
                className="product-card"
                style={{ transitionDelay: `${index * 100}ms` }}
                onClick={() => setSelectedProduct(product)}
              >
                <img src={product.image} alt={product.name} />
                <h3>{product.name}</h3>
              </div>
            ))}
          </div>
        </div>
      </section>

      {selectedProduct && (
        <div className="product-modal">
          <div className="modal-content">
            <button className="close-button" onClick={() => setSelectedProduct(null)}>×</button>
            <img src={selectedProduct.image} alt={selectedProduct.name} />
            <h2>{selectedProduct.name}</h2>
            <p>{selectedProduct.description}</p>
          </div>
        </div>
      )}
    </>
  );
};

export default Products;
